class CustomSubject extends DataClass implements Insertable<CustomSubject> {
  final int id;

  /// Slug used in routes and as `topic_resources.subject_id`.
  ///
  /// Unique, and validated against the bundled ids before insert so a teacher
  /// cannot create a second "chemistry" that shadows the bundled one — see
  /// [CustomSubjectService.create].
  final String subjectId;

  /// What the teacher typed, shown on the subject card.
  final String name;

  /// Icon key and card colour, using the same vocabulary as the bundled
  /// curriculum JSON so one card widget renders both kinds.
  final String icon;
  final String color;

  /// ISO-8601 UTC, matching `topic_resources.created_at`.
  final String createdAt;

  /// Null for a subject made on this (teacher) device. On a student device,
  /// the [ClassGroups.groupUuid] of the class whose teacher offered it — the
  /// teacher's subject list arrives on every sync and replaces these rows.
  final String? classGroupUuid;

  /// The teacher profile (`teacher_profiles.id`) that created this subject;
  /// only they may rename or delete it, or add materials to it. Null on a
  /// received subject. Local only, never synced.
  final int? ownerTeacherId;
  const CustomSubject({
    required this.id,
    required this.subjectId,
    required this.name,
    required this.icon,
    required this.color,
    required this.createdAt,
    this.classGroupUuid,
    this.ownerTeacherId,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['subject_id'] = Variable<String>(subjectId);
    map['name'] = Variable<String>(name);
    map['icon'] = Variable<String>(icon);
    map['color'] = Variable<String>(color);
    map['created_at'] = Variable<String>(createdAt);
    if (!nullToAbsent || classGroupUuid != null) {
      map['class_group_uuid'] = Variable<String>(classGroupUuid);
    }
    if (!nullToAbsent || ownerTeacherId != null) {
      map['owner_teacher_id'] = Variable<int>(ownerTeacherId);
    }
    return map;
  }

  CustomSubjectsCompanion toCompanion(bool nullToAbsent) {
    return CustomSubjectsCompanion(
      id: Value(id),
      subjectId: Value(subjectId),
      name: Value(name),
      icon: Value(icon),
      color: Value(color),
      createdAt: Value(createdAt),
      classGroupUuid: classGroupUuid == null && nullToAbsent
          ? const Value.absent()
          : Value(classGroupUuid),
      ownerTeacherId: ownerTeacherId == null && nullToAbsent
          ? const Value.absent()
          : Value(ownerTeacherId),
    );
  }

  factory CustomSubject.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return CustomSubject(
      id: serializer.fromJson<int>(json['id']),
      subjectId: serializer.fromJson<String>(json['subjectId']),
      name: serializer.fromJson<String>(json['name']),
      icon: serializer.fromJson<String>(json['icon']),
      color: serializer.fromJson<String>(json['color']),
      createdAt: serializer.fromJson<String>(json['createdAt']),
      classGroupUuid: serializer.fromJson<String?>(json['classGroupUuid']),
      ownerTeacherId: serializer.fromJson<int?>(json['ownerTeacherId']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'subjectId': serializer.toJson<String>(subjectId),
      'name': serializer.toJson<String>(name),
      'icon': serializer.toJson<String>(icon),
      'color': serializer.toJson<String>(color),
      'createdAt': serializer.toJson<String>(createdAt),
      'classGroupUuid': serializer.toJson<String?>(classGroupUuid),
      'ownerTeacherId': serializer.toJson<int?>(ownerTeacherId),
    };
  }

  CustomSubject copyWith({
    int? id,
    String? subjectId,
    String? name,
    String? icon,
