    required this.id,
    this.schoolId,
    this.schoolName,
    required this.signingSeed,
    this.boxSeed,
    this.deviceRole,
    required this.hostGeneration,
    this.failoverSealKey,
    this.failoverKdfSalt,
    this.failoverKdfRounds,
  });
