    if (!nullToAbsent || pinPlain != null) {
      map['pin_plain'] = Variable<String>(pinPlain);
    }
    map['created_at'] = Variable<String>(createdAt);
    if (!nullToAbsent || uuid != null) {
      map['uuid'] = Variable<String>(uuid);
    }
    return map;
  }

